#include <vector>
using namespace std;

class Solution {
public:
    /**
     * 方法一：三指標（荷蘭國旗）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    void sortColors(vector<int>& nums) {
        int left = 0;
        int right = nums.size() - 1;
        int current = 0;

        while (current <= right) {
            if (nums[current] == 0) {
                swap(nums[left], nums[current]);
                left++;
                current++;
            } else if (nums[current] == 1) {
                current++;
            } else {  // nums[current] == 2
                swap(nums[current], nums[right]);
                right--;
            }
        }
    }

    /**
     * 方法二：計數排序
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    void sortColors_counting(vector<int>& nums) {
        int count[3] = {0};

        for (int num : nums) {
            count[num]++;
        }

        int index = 0;
        for (int color = 0; color < 3; color++) {
            for (int i = 0; i < count[color]; i++) {
                nums[index++] = color;
            }
        }
    }
};

