class Solution {
    /**
     * 方法一：三指標（荷蘭國旗）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public void sortColors(int[] nums) {
        int left = 0;
        int right = nums.length - 1;
        int current = 0;

        while (current <= right) {
            if (nums[current] == 0) {
                swap(nums, left, current);
                left++;
                current++;
            } else if (nums[current] == 1) {
                current++;
            } else {  // nums[current] == 2
                swap(nums, current, right);
                right--;
            }
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

    /**
     * 方法二：計數排序
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public void sortColors_counting(int[] nums) {
        int[] count = new int[3];

        for (int num : nums) {
            count[num]++;
        }

        int index = 0;
        for (int color = 0; color < 3; color++) {
            for (int i = 0; i < count[color]; i++) {
                nums[index++] = color;
            }
        }
    }
}

