// 荷蘭國旗問題：三指標把 0 換到左邊、2 換到右邊
// 時間複雜度: O(n)，空間複雜度: O(1)
static void swap(int* a, int* b) { int t = *a; *a = *b; *b = t; }

void sortColors(int* nums, int numsSize) {
    int low = 0, mid = 0, high = numsSize - 1;
    while (mid <= high) {
        if (nums[mid] == 0) {
            swap(&nums[low++], &nums[mid++]);
        } else if (nums[mid] == 2) {
            swap(&nums[mid], &nums[high--]);   // 換過來的數還沒檢查，mid 不動
        } else {
            mid++;
        }
    }
}

